    "content": "import express from 'express';
import sqlite3 from 'sqlite3';
import bcryptjs from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { RateLimiter } from './rateLimiter.js';
import { validateEmail, validatePassword } from './validation.js';

const app = express();
const db = new sqlite3.Database(':memory:');
const loginLimiter = new RateLimiter(5, 15 * 60 * 1000); // 5 attempts per 15 min
const signupLimiter = new RateLimiter(3, 60 * 60 * 1000); // 3 signups per hour
const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-key-change-in-prod';

app.use(express.json());

// Init DB
db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY,
      email TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
});

app.post('/signup', async (req, res) => {
  const { email, password, confirmPassword } = req.body;
  const clientIp = req.ip;

  // Rate limit
  if (!signupLimiter.allow(clientIp)) {
    return res.status(429).json({ error: 'Too many signup attempts. Try again later.' });
  }

  // Validate
  if (!validateEmail(email)) {
    return res.status(400).json({ error: 'Invalid email format.' });
  }
  if (!validatePassword(password)) {
    return res.status(400).json({ error: 'Password must be at least 8 characters.' });
  }
  if (password !== confirmPassword) {
    return res.status(400).json({ error: 'Passwords do not match.' });
  }

  try {
    const hash = await bcryptjs.hash(password, 10);
    db.run('INSERT INTO users (email, password_hash) VALUES (?, ?)', [email, hash], (err) => {
      if (err) {
        if (err.message.includes('UNIQUE constraint failed')) {
          return res.status(409).json({ error: 'Email already registered.' });
        }
        return res.status(500).json({ error: 'Signup failed.' });
      }
      res.status(201).json({ message: 'User created. Log in to continue.' });
    });
  } catch (err) {
    res.status(500).json({ error: 'Server error.' });
  }
});

app.post('/login', async (req, res) => {
  const { email, password } = req.body;
  const clientIp = req.ip;

  // Rate limit on IP
  if (!loginLimiter.allow(clientIp)) {
    return res.status(429).json({ error: 'Too many failed attempts. Try again in 15 minutes.' });
  }

  if (!email || !password) {
    loginLimiter.recordFailure(clientIp);
    return res.status(400).json({ error: 'Email and password required.' });
  }

  db.get('SELECT id, email, password_hash FROM users WHERE email = ?', [email], async (err, user) => {
    if (err || !user) {
      loginLimiter.recordFailure(clientIp);
      return res.status(401).json({ error: 'Invalid credentials.' });
    }

    const match = await bcryptjs.compare(password, user.password_hash);
    if (!match) {
      loginLimiter.recordFailure(clientIp);
      return res.status(401).json({ error: 'Invalid credentials.' });
    }

    // Success: clear failures, issue token
    loginLimiter.recordSuccess(clientIp);
    const token = jwt.sign({ userId: user.id, email: user.email }, JWT_SECRET, { expiresIn: '7d' });
    res.json({ token, expiresIn: '7d' });
  });
});

app.get('/profile', (req, res) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token provided.' });

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    res.json({ userId: decoded.userId, email: decoded.email });
  } catch (err) {
    res.status(401).json({ error: 'Invalid or expired token.' });
  }
});

app.listen(3000, () => {
  console.log('Auth server running on http://localhost:3000');
});
